package com.amdocs.telecom.service; import com.amdocs.telecom.model.Types.SLAStatus; import java.sql.*; import java.time.*; public class SLAService{public Timestamp deadline(Timestamp created,int mins){return Timestamp.from(created.toInstant().plusSeconds(mins*60L));}public SLAStatus status(Timestamp d){long m=Duration.between(Instant.now(),d.toInstant()).toMinutes();return m<0?SLAStatus.BREACHED:m<=60?SLAStatus.AT_RISK:SLAStatus.WITHIN_SLA;} public long remainingMinutes(Timestamp d){return Duration.between(Instant.now(),d.toInstant()).toMinutes();}}
